  "schema_version": 1,
  "observations": [
    {
      "key": "obs_1",
      "facet": "mechanism",
      "statement": "heapq.merge merges multiple sorted inputs into a single sorted output.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_2",
      "facet": "property",
      "statement": "heapq.merge returns an iterator.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_3",
      "facet": "property",
      "statement": "heapq.merge does not pull the data into memory all at once.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_4",
      "facet": "precondition",
      "statement": "heapq.merge assumes each input stream is already sorted.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_5",
      "facet": "mechanism",
      "statement": "heapq.nsmallest and heapq.nlargest perform best for smaller values of n.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_6",
      "facet": "mechanism",
      "statement": "For larger values of n, it is more efficient to use sorted() than heapq.nsmallest/nlargest.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_7",
      "facet": "mechanism",
      "statement": "When n is one, min() or max() is more efficient than heapq.nsmallest/nlargest.",
      "start_line": 3,
      "end_line": 3
    },
    {
      "key": "obs_8",
      "facet": "mechanism",
      "statement": "If repeated usage is required, consider turning the iterable into an actual heap.",
      "start_line": 3,
      "end_line": 3
    }
  ],
